from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        INF = 10**9

        first_idx = [INF] * (max_group + 1)

        for i, x in enumerate(elements):
            if x <= max_group and first_idx[x] == INF:
                first_idx[x] = i

        best = [INF] * (max_group + 1)

        for x in range(1, max_group + 1):
            idx = first_idx[x]
            if idx == INF:
                continue

            for multiple in range(x, max_group + 1, x):
                if idx < best[multiple]:
                    best[multiple] = idx

        return [-1 if best[g] == INF else best[g] for g in groups]
